-- --------------------------------------
-- Salvage loot: what salvaging an item gives, item_loot is used by the salvage request (ClientItemUseLootBag).
-- Items with an archived Jabbithole "Salvaged to" table use it, gear uses per tier groups marked GUESS.
-- --------------------------------------
DELETE FROM `item_loot` WHERE `lootGroupId` BETWEEN 1101000000 AND 1101999999;
DELETE FROM `loot_item` WHERE `id` BETWEEN 1101000000 AND 1101999999;
UPDATE `loot_group` SET `parentId` = NULL WHERE `id` BETWEEN 1101000000 AND 1101999999;
DELETE FROM `loot_group` WHERE `id` BETWEEN 1101000000 AND 1101999999;

